def choose(kind, value):
    if kind == "one":
        return value + 1
    elif kind == "two":
        return value + 2
    elif kind == "three":
        return value + 3
    elif kind == "four":
        return value + 4
    elif kind == "five":
        return value + 5
    elif kind == "six":
        return value + 6
    elif kind == "seven":
        return value + 7
    elif kind == "eight":
        return value + 8
    elif kind == "nine":
        return value + 9
    elif kind == "ten":
        return value + 10
    elif kind == "eleven":
        return value + 11
    return value
